    println!("函数里拿到：{}", s);
    s
}

fn main() {
    let x = 42;
    let y = x;
    println!("Copy: x = {}, y = {}", x, y);

    let s1 = String::from("hello");
    let s2 = s1;
    // println!("{}", s1); // 取消注释会报 E0382：s1 已被 move
    println!("move 后：s2 = {}", s2);

    let s3 = String::from("hello");
    let s4 = s3.clone();
    println!("clone 后：s3 = {}, s4 = {}", s3, s4);

    let s5 = String::from("world");
    let s6 = takes_and_returns(s5);
    println!("拿回所有权后：s6 = {}", s6);

    {
        let s7 = String::from("临时");
        println!("作用域内：{}", s7);
    }
    println!("作用域已结束，s7 不可用（也不用 free）");
}

fn len_of(s: &str) -> usize {
    s.len()
}

fn append_exclaim(s: &mut String) {
    s.push('!');
}

fn main() {
    // 1. 不可变借用：可以同时有多个
    let s1 = String::from("hello");
    let r1 = &s1;
    let r2 = &s1;
    println!(
        "不可变借用：r1 = {}, r2 = {}, len = {}",
        r1,
        r2,
        len_of(&s1)
    );

    // 2. 可变借用：同一时刻只能有一个，且不能与不可变借用共存
    let mut s2 = String::from("rust");
    append_exclaim(&mut s2);
    println!("可变借用改完后：{}", s2);

    // 3. NLL：借用的作用域到最后一次使用为止，不是到花括号为止
    let mut s3 = String::from("borrow");
    let r3 = &s3;
    println!("先用不可变借用：{}", r3);
    // r3 在这里之后不再被使用，它的借用已经结束，
    // 所以下面再拿可变借用是合法的
    let r4 = &mut s3;
    r4.push('!');
    println!("借用结束后可再借可变：{}", s3);

    // 4. 借用不拥有数据：函数结束，借用结束，原变量还在
    let s4 = String::from("still mine");
    let n = len_of(&s4);
    println!("借出后原变量还在：{}（长度 {}）", s4, n);
}

fn first_word(s: &str) -> &str {
    let bytes = s.as_bytes();
    for (i, &item) in bytes.iter().enumerate() {
        if item == b' ' {
            return &s[..i];
        }
    }
    s
}

