fn main() {
    // 1. move 的修法：不需要拿走所有权时，传 &str 借用，原值还能继续用。
    let name = String::from("demo-process");
    print_name(&name);
    println!("after borrow: {name}");

    // 2. 借用冲突的修法：把只读借用的使用收进一个块里，借用结束后再可变操作。
    let mut nums = vec![10, 20, 30];
    {
        let first = &nums[0];
        println!("first: {first}");
    } // first 的借用在这里结束
    nums.push(40);
    println!("after push: {nums:?}");

    // 3. 悬垂的修法：不能返回指向局部变量的引用，返回自有的 String。
    let owned = make_greeting("world");
    println!("{owned}");

    // 4. 先把需要的值复制出来，再做可变操作，也是一种缩短借用的办法。
    let mut scores = vec![80, 90];
    let first_score = scores[0]; // i32 是 Copy，复制出来就不欠借用
    scores.push(100);
    println!("first_score: {first_score}, scores: {scores:?}");
}

