use std::error::Error;

fn level_of(line: &str) -> Option<&str> {
    line.split_whitespace().next()
}

fn code_of(line: &str) -> Result<u32, std::num::ParseIntError> {
    let code = line.split_whitespace().nth(2).unwrap_or("0");
    code.parse()
}

fn summarize(lines: &[&str]) -> Result<(usize, u32), Box<dyn Error>> {
    let mut errors = 0;
    let mut sum = 0;
    for line in lines {
        if level_of(line) == Some("ERROR") {
            errors += 1;
            sum += code_of(line)?;
        }
    }
    Ok((errors, sum))
}

fn main() -> Result<(), Box<dyn Error>> {
    let lines = [
        "INFO start 0",
        "ERROR disk 500",
        "WARN retry 0",
        "ERROR net 404",
    ];
    let (errors, sum) = summarize(&lines)?;
    println!("errors={errors} sum={sum}");
    println!("missing level: {:?}", level_of(""));
    println!("bad code: {:?}", code_of("ERROR x abc"));
    println!("ok code: {:?}", code_of("INFO ok 200"));
    Ok(())
}
